INSERT INTO legal_concepts (id, concept, category, subcategory, definition_simple, real_example, regulation, jurisprudence, video_url, key_points) VALUES
('DP-001', 'Capacidad Procesal', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Aptitud legal para comparecer vßlidamente en juicio, sea por sÝ o mediante representante legal. Difiere de la capacidad para ser parte, que es la idoneidad para figurar como sujeto en el proceso (toda persona natural o jurÝdica la tiene); la capacidad procesal exige mayorÝa de edad o habilitaci¾n legal.', 'Ej.: Un menor de edad debe litigar representado por su tutor, careciendo de capacidad procesal propia.', 'Art. 7 C¾digo de Procedimiento Civil (CPC) (los incapaces solo act·an por representante)', '', '', '["Se discute si la capacidad procesal es un presupuesto de existencia del proceso (vicio de incapacidad genera nulidad) o solo un requisito subsanable", "Doctrina unßnime la considera requisito indispensable, pero la jurisprudencia ha permitido subsanar representaciones defectuosas durante el juicio para evitar nulidades innecesarias ."]'),
('DP-002', 'Litisconsorcio', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Situaci¾n en que varias personas act·an como demandantes o demandados en un mismo juicio, compartiendo un interest jurÝdico com·n. Puede ser voluntario (partes deciden litigar conjuntamente) o necesario (la ley exige la presencia de todos los interesados).', 'Ej.: Dos copropietarios presentan juntos una demanda (litisconsorcio activo) o un deudor y su codeudor son demandados simultßneamente (litisconsorcio pasivo) en un mismo proceso.', 'Art. 18 CPC (autoriza litigar conjuntamente cuando la acci¾n emane de un mismo hecho o derecho)', '', '', '["Debate doctrinal sobre litisconsorcio necesario: algunos sostienen que la sentencia es nula si no comparecen todos los sujetos jurÝdicamente ligados (p. ej., todos los cotitulares de un derecho real)", "Otros estiman que el juez puede instar la integraci¾n de tales partes ausentes antes de fallar, privilegiando la economÝa procesal sobre formalidades ."]'),
('DP-003', 'Patrocinio y Poder', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Regla general que exige que las partes comparezcan en juicio representadas por un abogado habilitado (patrocinio) y mediante un mandato judicial otorgado (poder). El patrocinio se acredita con la firma del abogado en los escritos, y el poder con el instrumento que faculta al mandatario para actuar en nombre de la parte.', 'Ej.: En una demanda civil de mayor cuantÝa, el demandante otorga poder ante notario a un abogado y este patrocina el escrito inicial, cumpliendo con la exigencia legal.', 'Arts. 1, 4, 6 CPC (obligatoriedad de comparecer por medio de abogado patrocinante y mandatario con poder suficiente)', '', '', '["Tensi¾n prßctica: la ausencia de poder o patrocinio vßlido puede llevar to la nulidad de lo obrado, pero la jurisprudencia tiende a conceder oportunidades de subsanar (aportar poder dentro de plazo) para no sacrificar el fondo por defectos formales", "Discusi¾n doctrinal sobre si el vicio de falta de patrocinio es saneable o causa de inadmisibilidad radical de la demanda ."]'),
('DP-004', 'Notificaciones', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Acto formal por el cual se comunica a las partes el contenido de las resoluciones judiciales, para que produzcan efecto. La primera notificaci¾n de la demanda debe ser personal al demandado, y en general ninguna resoluci¾n genera efecto si no ha sido notificada conforme a la ley.', 'Ej.: El auto de apertura de prueba se notifica por cÚdula al abogado del demandado en su domicilio registrado. Solo desde esa notificaci¾n comienza a correr el plazo probatorio.', 'Arts. 38 y ss. CPC (toda resoluci¾n surte efecto con notificaci¾n legal; requisitos de notificaci¾n personal, por cÚdula, por avisos, etc.)', 'Corte Suprema, 02.07.2019, Rol 13.122-2019 (anul¾ todo lo obrado tras notificaci¾n defectuosa, reiterando que la notificaci¾n invßlida vulnera la bilateralidad de la audiencia)', '', '["Se contraponen posturas: estricta sujeci¾n a las formalidades (vicios en notificaciones acarrean nulidad ipso iure) vs. la postura teleol¾gica que exige demostrar indefensi¾n efectiva para anular por notificaci¾n viciada", "La jurisprudencia reciente exige analizar caso a caso si la notificaci¾n defectuosa caus¾ perjuicio, modulando asÝ la sanci¾n de nulidad procesal."]'),
('DP-005', 'Plazos Procesales', 'Derecho Procesal', 'Reglas Comunes a Todo Procedimiento', 'Periodos de tiempo fijados por la ley o el tribunal para realizar actos procesales. Por regla general son fatales (su inobservancia extingue el derecho a actuar) y se computan en dÝas hßbiles judiciales. Comienzan a correr desde la medianoche del dÝa de la notificaci¾n respectiva, salvo rÚgimen especial de ampliaci¾n por distancia.', 'Ej.: En un juicio ordinario civil, el demandado tiene 15 dÝas para contestar la demanda si fue notificado dentro del territorio jurisdiccional del tribunal; vencido ese plazo sin contestaci¾n, queda en rebeldÝa.', 'Arts. 258-259 CPC (plazos para contestar demanda seg·n distancia); Art. 66 CPC (plazos fatales y prorrogables)', '', '', '["CrÝtica recurrente: la fatalidad estricta de los plazos puede chocar con la tutela judicial efectiva. Tribunales han flexibilizado plazos solo en casos excepcionales (fuerza mayor, artÝculo 79 CPC)", "Doctrina propone instaurar un rÚgimen de ôplazos interrumpiblesö o conceder al juez facultad de extensi¾n por razones fundadas, lo cual se enfrenta al principio de certeza y preclusi¾n propio de la seguridad procesal."]'),
('DP-008', 'Juez Natural', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', 'Principio fundamental seg·n el cual toda persona tiene derecho a ser juzgada por tribunales ordinarios previamente establecidos por la ley, competentes para la materia y territorio del caso. Se prohÝben los tribunales de excepci¾n o comisiones especiales creados ex post hecho.', 'Ej.: Un funcionario acusado de un delito com·n serß juzgado por el tribunal penal ordinario que se±ala la ley y no por una comisi¾n ad-hoc. Del mismo modo, un civil no puede ser juzgado por un tribunal militar si la ley no lo contempla (resguardo del juez natural).', 'Art. 19 N░3 Constituci¾n PolÝtica; Art. 2 COT (proscribe comisiones especiales, exige tribunal establecido con anterioridad)', '', '', '["Conflicto notorio en estados de excepci¾n: algunos han intentado crear tribunales especiales (v.g. consejos de guerra, tribunales militares a civiles); la doctrina y la jurisprudencia los han declarado inconstitucionales por infringir el juez natural", "Asimismo, se debate si la designaci¾n de ministros visitadores o jueces suplentes para descongestionar causas viola el principio; la Corte Suprema ha resuelto que, mientras estÚn autorizados por ley con antelaci¾n, no se vulnera la garantÝa del juez natural ."]'),
('DP-009', 'Tribunales Ordinarios vs. Especiales', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', 'Los tribunales ordinarios son aquellos del Poder Judicial con competencia general (Corte Suprema, Cortes de Apelaciones, tribunales de juicio oral, juzgados de letras y de garantÝa), mientras que los especiales conocen materias especÝficas y se rigen por leyes orgßnicas particulares (juzgados de familia, laborales, militares en tiempo de paz, etc.).', 'Ej.: Un conflicto de familia se ve ante un Juzgado de Familia (tribunal especial); en cambio, un caso civil patrimonial se ventila en un Juzgado de Letras civil (tribunal ordinario).', 'Art. 5 COT (integrantes del Poder Judicial ordinario y enumeraci¾n de tribunales especiales)', '', '', '["Debate actual: la proliferaci¾n de tribunales especiales podrÝa afectar la unidad jurisdiccional. Algunos critican la ôespecializaci¾n excesivaö (familia, laboral, etc.) que fragmenta criterios jurisprudenciales", "Otros defienden que la especializaci¾n mejora la eficiencia y conocimientos tÚcnicos. La tensi¾n se refleja en discusiones sobre si ciertas materias (p.ej. corrupci¾n, medio ambiente) deben radicarse en tribunales especializados o seguir bajo los ordinarios con capacitaci¾n especÝfica."]'),
('DP-010', 'Recusaci¾n e Implicancia', 'Derecho Procesal', 'Disposiciones Orgßnicas (Tribunales)', 'Mecanismos para asegurar la imparcialidad del juez. La implicancia opera de pleno derecho ante causales objetivas tasadas (parentesco cercano con una parte, interÚs en el pleito, etc.), obligando al juez a abstenerse. La recusaci¾n es solicitada por una parte cuando concurre alguna causal legal de desconfianza en la imparcialidad del juez (ej. enemistad grave, amistad Ýntima, interÚs indirecto) y no se ha abstenido voluntariamente.', 'Ej.: En un juicio donde el juez es hermano del demandante, existe causal de implicancia (parentesco de segundo grado) que lo inhabilita automßticamente (Art. 196 COT); si el juez no se aparta, la parte demandada puede deducir recusaci¾n para apartarlo.', 'Arts. 195-200 COT (listas de causales de implicancia y recusaci¾n, p. ej. parentesco, amistad/enemistad manifiesta, haber sido abogado en el caso, etc.)', 'CS, 30.07.2018 (Rol 12358-2018): Rechaz¾ recusaci¾n contra ministro de Corte Suprema por ôsentimientos negativosö del recurrente, al no configurar causal legal de implicancia ni probarse infracci¾n a la imparcialidad', '', '["Jurisprudencia exige pruebas concretas de parcialidad: ha descartado meras sospechas o diferencias de criterio como fundamento de recusaci¾n. Se discute si debe ampliarse el catßlogo de causales (por ej., perspectiva de gÚnero en caso de jueces con expresiones prejuiciosas) o mantener un elenco estricto para evitar recusaciones dilatorias."]'),
('DP-012', 'Contestaci¾n de la Demanda', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Escrito mediante el cual el demandado responde a la demanda, aceptando o negando los hechos alegados y formulando sus defensas. Debe contener la individualizaci¾n del tribunal y partes, las excepciones dilatorias si las hubiere, la contestaci¾n de fondo con una exposici¾n precisa de los hechos que se admiten o controvierten y los fundamentos jurÝdicos de su defensa, pudiendo incluir ademßs demandas reconvencionales.', 'Ej.: En un juicio por incumplimiento contractual, el demandado contesta negando haber incumplido, ofreciendo su propia versi¾n de los hechos (p. ej., alega caso fortuito) y planteando la excepci¾n de falta de legitimaci¾n activa, todo dentro del plazo legal de 15 dÝas desde la notificaci¾n.', 'Art. 309 CPC (contenido de la contestaci¾n: requisitos similares a la demanda, indicando tribunal, partes, aceptaci¾n o negaci¾n de hechos, defensas de fondo)', '', '', '["Cuesti¾n debatida: si el demandado no contest¾ (rebeldÝa), ┐puede el juez tener por confesados los hechos? En Chile rige que la rebeldÝa no importa aceptaci¾n tßcita de la demanda, debiendo igualmente el actor probar sus dichos (a diferencia de otros sistemas). Jurisprudencia uniforme: la incomparecencia no exime al demandante de acreditar sus hechos constitutivos, aunque se le facilite la prueba al no haber controversia explÝcita ."]'),
('DP-013', 'Conciliaci¾n', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Actuaci¾n procesal en la fase inicial del juicio ordinario en que el juez procura que las partes logren un avenimiento. Ocurre normalmente tras la etapa de discusi¾n (demanda y contestaci¾n). El juez de oficio cita a una audiencia de conciliaci¾n y, obrando como amigable componedor, propone f¾rmulas de arreglo. Si no se logra acuerdo total o parcial, se deja constancia y contin·a el juicio.', 'Ej.: En un juicio ordinario sobre indemnizaci¾n de perjuicios, el juez convoca a las partes a una audiencia de conciliaci¾n. Propone que el demandado pague la mitad de lo pedido en un plazo, pero si las partes no aceptan, se certifica el fracaso de la conciliaci¾n y se prosigue a fijar los puntos de prueba.', 'Arts. 262-264 CPC (obligatoriedad de citar a conciliaci¾n; papel del juez como componedor; acta de avenimiento si hay acuerdo)', '', '', '["Punto crÝtico: tradicionalmente se discutÝa si la falta de realizaci¾n de la audiencia de conciliaci¾n era nulidad procesal. La Corte Suprema ha resuelto que la omisi¾n de intentar la conciliaci¾n no genera nulidad de oficio, salvo que se acredite perjuicio, pues su finalidad es fomentar acuerdos pero no es requisito de validez del fallo", "Asimismo, se advierte tensi¾n entre el rol activo del juez en conciliar y su imparcialidad: un sector doctrinal estima que no debe presionar a las partes a transigir, para no prejuzgar, mientras otro defiende su deber de promover acuerdos para descongestionar el sistema ."]'),
('DP-014', 'Periodo Probatorio', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Etapa del juicio, abierta mediante resoluci¾n ôautos a pruebaö, en la que las partes rinden la prueba de los hechos controvertidos fijados por el tribunal. El tÚrmino probatorio ordinario es com·n para ambas partes y dura 20 dÝas hßbiles cuando la prueba debe rendirse dentro de la jurisdicci¾n, con posibles ampliaciones si se requiere practicar diligencias fuera del territorio o en el extranjero.', 'Ej.: En un juicio ordinario, fijados como puntos de prueba el incumplimiento del contrato y sus da±os, las partes disponen de 20 dÝas para presentar testigos, peritajes y documentos pertinentes; si se requieren testigos que residen lejos, el tribunal concede 30 dÝas adicionales por la distancia (tabla de emplazamiento).', 'Arts. 328-329 CPC (duraci¾n del tÚrmino probatorio ordinario y aumento por distancia)', '', '', '["Controversia doctrinal sobre el rol del juez en la etapa probatoria: el sistema chileno se adscribe a la aportaci¾n de parte, donde el tribunal es relativamente pasivo y solo valora lo presentado seg·n la sana crÝtica. Sin embargo, existe debate si debiera otorgarse al juez mayores facultades probatorias de oficio (medidas para mejor resolver) para descubrir la verdad material", "La jurisprudencia, especialmente en sede civil, es restrictiva en admitir prueba ex officio, lo que algunos critican por supeditar la justicia a la habilidad o recursos de las partes."]'),
('DP-015', 'Sentencia', 'Derecho Procesal', 'Juicio Ordinario de Mayor CuantÝa', 'Decisi¾n judicial que pone fin al juicio, resolviendo las pretensiones planteadas. La sentencia definitiva debe contener, seg·n el Art. 170 CPC: la designaci¾n del tribunal y partes, consideraciones de hecho y de derecho que fundan el fallo, y la parte dispositiva que acoge o rechaza las peticiones. Se exige que sea fundada, congruente con lo litigado y dictada por juez imparcial.', 'Ej.: En un juicio ordinario sobre incumplimiento contractual, la sentencia definitiva expone los hechos probados (existencia del contrato, incumplimiento del demandado), los fundamentos jurÝdicos (art. 1545 CC, fuerza obligatoria de contratos) y decide acoger la demanda, condenando al demandado a pagar cierta suma, con costas.', 'Arts. 158 y 170 CPC (definici¾n de sentencia definitiva y requisitos formales de toda sentencia: motivaciones y parte resolutiva)', 'Corte Suprema, 21.01.2019, Rol 40166-2017: Invalid¾ de oficio una sentencia de la CA de Talca por falta de fundamentaci¾n, reiterando que la ausencia de consideraciones de hecho o derecho esenciales infringe el Art. 170 CPC y constituye causal de casaci¾n en la forma.', '', '["Se plantea el dilema entre exigencia de motivaci¾n vs. brevedad: la jurisprudencia ha anulado fallos por motivaci¾n aparente o insuficiente, enfatizando el derecho a una sentencia razonada (debido proceso)", "Sin embargo, se advierte riesgo de ôjurisprudencia de mÚritoö si la Corte Suprema eval·a excesivamente la fundamentaci¾n, invadiendo competencias del fondo. La discusi¾n se refleja en c¾mo distinguir entre falta de consideraciones (vicio formal) y mera divergencia en la valoraci¾n probatoria (no casable en la forma)."]'),
('DP-016', 'TÝtulo Ejecutivo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Documento al cual la ley confiere mÚrito suficiente para demandar coactivamente una obligaci¾n en sede ejecutiva, sin necesidad de juicio declarativo previo. Debe contener una obligaci¾n clara, actualmente exigible y liquidable. Ejemplos tÝpicos: una sentencia firme condenatoria, un pagarÚ o cheque protestado, una escritura p·blica reconociendo deuda, etc., enumerados en el Art. 434 CPC.', 'Ej.: Un pagarÚ vencido y debidamente protestado, firmado ante notario, es un tÝtulo ejecutivo contra el deudor por el capital e intereses allÝ consignados.', 'Art. 434 CPC (enumeraci¾n de tÝtulos con fuerza ejecutiva: sentencias firmes, instrumentos p·blicos, instrumentos privados reconocidos ante juez, cheques, pagarÚs con requisitos, etc.)', 'Corte Suprema, 14.01.2026 (Rol 13.345-2025): Declar¾ que un pagarÚ firmado bajo condici¾n suspensiva carece de mÚrito ejecutivo mientras la condici¾n no se cumpla, reiterando que solo obligaciones actualmente exigibles pueden ejecutarse.', '', '["Debate jurisprudencial sobre tÝtulos incompletos o alterados: por ej., pagarÚs con espacios en blanco llenados sin autorizaci¾n han sido negados como ejecutivos por la Corte (falta de exigibilidad clara)", "TambiÚn se discute la validez ejecutiva de contratos con clßusulas aceleratorias automßticas: tendencia judicial a aceptarlos como ejecutivos siempre que la clßusula estÚ pactada expresamente, mientras la doctrina advierte riesgo de extender la vÝa ejecutiva a supuestos no previstos estrictamente en la ley."]'),
('DP-017', 'Mandamiento de Ejecuci¾n y Embargo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Resoluci¾n inicial que despacha la ejecuci¾n forzada. Contiene la orden al receptor judicial de requerir de pago al deudor por la suma demandada y, no pagando, embargar bienes suficientes para responder. Su notificaci¾n personal al ejecutado es requisito esencial. Marca el comienzo del procedimiento de apremio (embargos, realizaci¾n de bienes).', 'Ej.: Admitida a trßmite la demanda ejecutiva fundada en un pagarÚ, el tribunal emite mandamiento ordenando al receptor: ôRequÝÚrase de pago al deudor X por $10 millones y c·mplase embargo sobre sus bienes suficientes si no pagaö. El receptor concurre al domicilio del deudor, lo notifica y embargas bienes (ej. un vehÝculo) ante la falta de pago inmediato.', 'Arts. 442-443 CPC (contenido del mandamiento: requerimiento de pago personal y embargo en caso de no pago)', '', '', '["Un tema prßctico es el cumplimiento efectivo de la notificaci¾n personal: la jurisprudencia exige agotar diligencias para notificar personalmente el mandamiento, ya que de ello depende vßlidamente la traba de embargo y el curso de la ejecuci¾n. Se discute si la notificaci¾n por cÚdula del mandamiento (permitida tras intento fallido personal) vulnera garantÝas del deudor; la postura dominante la admite, siempre que se acrediten esfuerzos razonables de notificaci¾n personal previos, conciliando eficacia del cobro y debido proceso."]'),
('DP-018', 'Excepciones del Juicio Ejecutivo', 'Derecho Procesal', 'Juicios Ejecutivos', 'Defensas especÝficas y taxativas que el ejecutado puede oponer dentro del breve plazo legal (4 dÝas) para paralizar o invalidar la ejecuci¾n. Estßn enumeradas en el Art. 464 CPC e incluyen, entre otras: incompetencia del tribunal, incapacidad del demandante, litispendencia, ineptitud del libelo, falsedad o falta de requisitos del tÝtulo, pago o extinci¾n de la obligaci¾n, prescripci¾n, cosa juzgada, etc.. Solo estas excepciones pueden alegarse en sede ejecutiva.', 'Ej.: Frente a una ejecuci¾n hipotecaria, el deudor puede oponer la excepci¾n de pago (numeral 9 del Art. 464 CPC) acreditando que ya cancel¾ la deuda, o la excepci¾n de prescripci¾n de la acci¾n ejecutiva (numeral 17) si ha transcurrido el plazo legal, con lo cual busca que se termine el juicio ejecutivo..', 'Art. 464 CPC (numerales 1░ al 18░, listado completo de excepciones admisibles en juicio ejecutivo)', '', '', '["La jurisprudencia es estricta en la taxatividad: no admite defensas fuera del catßlogo del Art. 464. Por ej., intentos de oponer ôabuso de derechoö o ôlesi¾n enormeö como excepci¾n han sido rechazados por no figurar en la lista legal. CrÝtica doctrinal: el sistema puede ser excesivamente rÝgido, impidiendo alegar situaciones de injusticia no previstas expresamente. Sin embargo, los tribunales se±alan que el ejecutado conserva la vÝa ordinaria (juicio de conocimiento posterior) para discutir aspectos no incluidos en las excepciones ejecutivas, salvaguardando el debido proceso sin desnaturalizar la ejecuci¾n."]'),
('DP-019', 'Remate', 'Derecho Procesal', 'Juicios Ejecutivos', 'Acto de subasta p·blica de los bienes embargados al ejecutado, ordenado por sentencia de remate o mandamiento firme, para convertirlos en dinero y pagar al acreedor con el producto. Debe realizarse con publicidad y bajo las bases fijadas por el tribunal (mÝnimo, forma de pago, cauciones). Se anuncia mediante avisos en diarios locales al menos por 4 veces antes de la fecha de subasta.', 'Ej.: En una ejecuci¾n hipotecaria, una vez dictada la sentencia de remate, se publica en un diario de la comuna un aviso indicando que el inmueble del deudor se subastarß tal dÝa en el juzgado, con postura mÝnima de $50 millones. El dÝa del remate, se presentan postores, se adjudica al mejor oferente y este debe consignar el precio seg·n lo establecido.', 'Arts. 488-495 CPC (procedimiento del remate: publicaciones, posturas, pago del precio, acta de remate, sanciones por incumplimiento del adjudicatario)', '', '', '["Problemßticas frecuentes: remates desiertos (sin postores) obligan a rebajar mÝnimum o a prenda pretoria en favor del acreedor, lo cual se ha criticado como posible enriquecimiento del ejecutante. La jurisprudencia ha abordado tambiÚn nulidades de remate por vicios en la publicidad o colusi¾n entre postores: ha dejado sin efecto subastas cuando no se cumpli¾ con los avisos legales o hubo maquinaciones para bajar el precio, ponderando el equilibrio entre seguridad jurÝdica del remate y protecci¾n del deudor contra liquidaciones irrisorias."]'),
('DP-020', 'TercerÝas', 'Derecho Procesal', 'Juicios Ejecutivos', 'Intervenciones de terceros en un juicio ejecutivo para reclamar derechos propios sobre los bienes embargados o el producto de ellos. Solo se admiten en cuatro casos: 1) tercerÝa de dominio (tercero alega ser due±o de los bienes embargados); 2) de posesi¾n (alega tenencia legÝtima); 3) de prelaci¾n (tercero acreedor con crÚdito privilegiado que pide ser pagado antes); 4) de pago (tercero solicita se le pague a Úl con lo obtenido).', 'Ej.: A un ejecutado se le embarga un vehÝculo, pero un tercero presenta una tercerÝa de dominio afirmando que el auto le pertenece (p. ej., por compraventa anterior). El tercerista deberß probar su dominio en un juicio incidental; mientras tanto, el remate del bien embargado podrÝa suspenderse o el dinero quedar consignado en custodia hasta resolver la tercerÝa.', 'Arts. 518-525 CPC (regulan las tercerÝas: procedencia, tramitaci¾n separada de la de dominio por juicio ordinario breve, tercerÝa de prelaci¾n/pago como incidentes, efectos sobre el procedimiento de apremio)', '', '', '["Un punto de fricci¾n es el uso malicioso de tercerÝas para entorpecer la ejecuci¾n: la jurisprudencia exige seriedad en la prueba del derecho invocado por el tercerista. Por eso, el Art. 522 CPC impide suspender la ejecuci¾n salvo que la tercerÝa de dominio se apoye en tÝtulo p·blico anterior a la demanda. Se discute si la tercerÝa de dominio deberÝa resolverse mßs ßgilmente (vvia incidental) para evitar dilaciones, pero ello podrÝa comprometer el debido proceso del tercerista; la soluci¾n de equilibrio ha sido mantener el juicio ordinario para dominio, pero permitiendo al acreedor pedir cauci¾n al tercerista para no frenar injustificadamente el remate."]'),
('DP-062', 'Recurso de Apelaci¾n', 'Derecho Procesal', 'Recursos Procesales', 'Medio de impugnaci¾n ordinario que permite a la parte agraviada por una resoluci¾n judicial obtener su revisi¾n por el tribunal superior. El fin de la apelaci¾n es que el superior corrija con arreglo a derecho la resoluci¾n del inferior, pudiendo confirmar, revocar o modificar lo decidido. En materia civil procede contra sentencias definitivas de primera instancia y ciertas interlocutorias, seg·n reglas legales.', 'Ej.: En un juicio civil, la sentencia del Juzgado de Letras que rechaza la demanda puede ser apelada por el demandante ante la Corte de Apelaciones respectiva, la cual reexaminarß el caso y dictarß su propio fallo confirmatorio o revocatorio del de primera instancia.', 'Arts. 186-193 CPC (objeto, plazo y efectos de la apelaci¾n; apelaciones en ambos efectos o solo devolutivo seg·n el caso)', '', '', '["Tensi¾n prßctica: el derecho a la doble instancia vs. la necesidad de celeridad. En Chile, la apelaci¾n en materia civil generalmente se concede en ambos efectos (suspensivo y devolutivo), lo que prolonga la ejecuci¾n del fallo. Se ha propuesto limitar apelaciones o conceder solo efecto devolutivo en ciertos casos para acelerar procesos, pero se advierte que podrÝa menoscabar garantÝas. La jurisprudencia ha equilibrado admitiendo adhesi¾n a la apelaci¾n y consolidando el estßndar de la ôno reformatio in peiusö (el apelante ·nico no puede quedar en peor situaci¾n tras la apelaci¾n), protegiendo el derecho de defensa en la segunda instancia."]'),
('DP-063', 'Recurso de Casaci¾n en la Forma', 'Derecho Procesal', 'Recursos Procesales', 'Recurso extraordinario que busca invalidar una sentencia viciada por errores procedimentales graves. Se funda en causales taxativas (Art. 768 CPC), como: tribunal incompetente, ultra petita (fallo otorga mßs de lo pedido), sentencia incongruente o falta de fundamentaci¾n, entre otras. Apunta a anular el fallo por infracci¾n a las formas sustanciales del procedimiento.', 'Ej.: Tras una sentencia de segunda instancia que omiti¾ pronunciarse sobre una excepci¾n sustancial alegada (omisi¾n que vulnera el debido proceso), la parte afectada interpone casaci¾n en la forma ante la Corte Suprema invocando la causal del N░5 del Art. 768 CPC (omisi¾n de consideraciones), solicitando la nulidad del fallo y la emisi¾n de uno nuevo correctamente motivado.', 'Arts. 767-768 CPC (procedencia de casaci¾n en sentencias inapelables; causales formales especÝficas)', 'Corte Suprema, 21.01.2019, Rol 40166-2017: Acogi¾ de oficio casaci¾n en la forma contra una sentencia de la CA Talca, por faltar las consideraciones de hecho y derecho (causal del Art. 768 N░5 CPC), invalidando el fallo y ordenando sentencia nueva.', '', '["Se discute si la casaci¾n en la forma debe interpretarse restrictivamente por su naturaleza extraordinaria o si la Corte Suprema ha ampliado su alcance indebidamente. Algunos acadÚmicos critican un ôformalismo excesivoö cuando se acoge casaci¾n por vicios menores sin trascendencia real en el resultado", "No obstante, la Corte ha reiterado que las formalidades esenciales son garantÝa de un debido proceso, prevaleciendo la nulidad cuando se verifica una causal, aunque existan fallos (minorÝa) en que la CS ha declarado el principio de conservaci¾n del acto procesal, desestimando casaciones formales por aplicaci¾n de la teorÝa del perjuicio (vgr., CAS 37.233-2019)."]'),
('DP-064', 'Recurso de Casaci¾n en el Fondo', 'Derecho Procesal', 'Recursos Procesales', 'Recurso extraordinario ante la Corte Suprema, procedente contra sentencias definitivas o interlocutorias inapelables de tribunales superiores, cuando en ellas se ha infringido la ley sustantiva y dicha infracci¾n ha influido substancialmente en lo dispositivo del fallo. Busca la correcta aplicaci¾n del derecho objetivo, mßs que la revisi¾n de los hechos del caso.', 'Ej.: Una Corte de Apelaciones confirma una sentencia pero aplica err¾neamente una norma de prescripci¾n, calculando mal el plazo. La parte perjudicada interpone casaci¾n en the fondo por infracci¾n de ley (artÝculo de prescripci¾n del CC) ante la Corte Suprema, para que anule lo resuelto y dicte sentencia conforme a la norma bien interpretada.', 'Arts. 766-772 CPC (requisitos y causales de casaci¾n de fondo: quebrantamiento de ley sustancial decisiva)', 'CS, 28.02.2020, Rol 29.411-2019: Acogi¾ casaci¾n en the fondo y anul¾ sentencia laboral que habÝa aplicado incorrectamente la norma de indemnizaci¾n por a±os de servicio, corrigiendo el cßlculo a favor del trabajador', '', '["Existe fricci¾n entre el rol unificador de la Corte Suprema e el respeto a la soberanÝa del tribunal de instancia en la valoraci¾n de la prueba. La casaci¾n en el fondo no puede revisar hechos, solo derecho, pero en ocasiones la lÝnea se difumina: crÝticos acusan a la Corte de revalorar implÝcitamente prueba so pretexto de error de derecho. A su vez, se plantea instaurar un recurso de unificaci¾n de jurisprudencia mßs amplio (como existe en laboral) para resolver discrepancias sin necesidad de invocar errores in procedendo o in iudicando estrictos."]'),
('DP-024', 'Recurso de Queja', 'Derecho Procesal', 'Recursos Procesales', 'Recurso de carßcter disciplinario que se interpone ante una Corte superior (Corte de Apelaciones o Suprema, seg·n el caso) para corregir faltas o abusos graves cometidos por un juez en la dictaci¾n de una resoluci¾n no susceptible de recursos ordinarios ni extraordinarios. Su objetivo es tutelar la recta administraci¾n de justicia sancionando al juez infractor y enmendando el perjuicio causado por su resoluci¾n.', 'Ej.: Una Corte de Apelaciones dicta una sentencia definitiva inapelable en un recurso de protecci¾n con manifiesto error jurÝdico y con posible arbitrariedad. La parte afectada presenta recurso de queja ante la Corte Suprema acusando falta grave en la decisi¾n, solicitando se deje sin efecto el fallo y se sancione disciplinariamente a los ministros que incurrieron en el abuso.', 'Art. 545 COT (procede queja por falta o abuso grave en sentencia interlocutoria o definitiva inapelable)', 'CS, 24.11.2025, Rol 250.587-2023: Rechaz¾ queja contra una Corte que declar¾ prescrita una acci¾n penal, enfatizando que una mera discrepancia en la interpretaci¾n de la ley no configura por sÝ sola falta o abuso grave que dÚ lugar a la queja.', '', '["La Corte Suprema ha limitado el alcance de la queja: ha reiterado que no es una ôtercera instanciaö para revisar el fondo de los asuntos, sino un mecanismo estrictamente disciplinario. Solo procede ante actuaciones judiciales aberrantes sin remedio recursal. Se debate si su uso actual desborda lo disciplinario (corrigiendo errores jurÝdicos bajo la etiqueta de abuso grave) o si, por el contrario, la CS ha sido correcta al restringirlo, como en fallos donde declara improcedente la queja cuando existen recursos legales disponibles o la cuesti¾n es de mera discrepancia jurÝdica."]'),
('DP-065', 'Recurso de Reposici¾n', 'Derecho Procesal', 'Recursos Procesales', 'Medio de impugnaci¾n horizontal, por el cual una parte solicita al mismo tribunal que dict¾ una resoluci¾n de trßmite (autos, decretos o ciertas interlocutorias) que la reconsidere o enmiende, por estimarla err¾nea o perjudicial. Se interpone dentro de un breve plazo (generalmente 3 dÝas) desde la notificaci¾n de la resoluci¾n y puede ser con o sin ôapelaci¾n en subsidioö.', 'Ej.: El juez dicta una resoluci¾n que rechaza por extemporßneo un escrito de prueba; la parte afectada interpone reposici¾n dentro de 3 dÝas argumentando que present¾ el escrito en plazo hßbil, pidiendo al mismo juez que revoque su decisi¾n. Si el juez rechaza la reposici¾n, queda expedita la apelaci¾n subsidiaria si se interpuso.', 'Art. 81 CPC (procedencia de reposici¾n contra autos y decretos dentro de tercero dÝa); Art. 362 C¾digo Procesal Penal (reposiciones en procedimiento penal)', '', '', '["Se discute la efectividad real de la reposici¾n: muchos la consideran de escasa incidencia ya que el mismo juez raramente cambia su criterio, sirviendo principalmente para agotar instancia o dejar constancia para una eventual apelaci¾n. Sin embargo, en prßctica ha permitido corregir errores evidentes (p. ej., cßlculos aritmÚticos, citas legales equivocadas) sin necesidad de acudir al superior", "Algunos tribunales resuelven de plano las reposiciones, otros las oyen ôcon audienciaö de la contraparte; la falta de uniformidad ha generado debate sobre si la reposici¾n debe otorgar siempre traslado para mayor bilateralidad, o si ello la harÝa demasiado lenta contraviniendo su naturaleza expedita."]'),
('DP-026', 'Principio Acusatorio', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Eje del nuevo sistema penal chileno que separa las funciones de investigar, acusar y juzgar. La persecuci¾n penal la dirige en forma exclusiva el Ministerio P·blico, mientras un juez de garantÝa imparcial controla la legalidad del procedimiento y otro tribunal (Tribunal de Juicio Oral) resuelve sobre la culpabilidad. Implica oralidad, publicidad, contradicci¾n y que el juez no act·a de oficio en la investigaci¾n (a diferencia del antiguo sistema inquisitivo).', 'Ej.: Ante un delito, el fiscal re·ne evidencias e imputa cargos, el juez de garantÝa vela por los derechos del imputado (p. ej., autorizando cautelares si proceden) y finalmente un tribunal oral colegiado decide la condena o absoluci¾n en juicio. El juez no investiga por sÝ mismo, respetando la divisi¾n acusador/juzgador.', 'Arts. 1, 3 C¾digo Procesal Penal (CPP) (juicio previo ante tribunal imparcial; investigaci¾n a cargo exclusivo del MP)', '', '', '["Tensi¾n prßctica: si bien el fiscal conduce la investigaci¾n, se cuestiona el ôdesequilibrioö de poderes, pues la defensa depende de lo aportado por el MP. Algunos critican que el principio acusatorio llev¾ a un juez mßs pasivo; sin embargo, la jurisprudencia ha perfilado un juez de garantÝa activo en cautelar derechos fundamentales (anulando actuaciones viciadas o controlando plazos), lo que equilibra el sistema", "El debate persiste en torno a figuras hÝbridas como el juez de la investigaci¾n propuesto en ciertas reformas, que a juicio de detractores reintroducirÝa elementos inquisitivos, mientras defensores alegan que fortalecerÝa la eficacia investigativa sin menoscabar garantÝas."]'),
('DP-027', 'Formalizaci¾n de la Investigaci¾n', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Acto procesal mediante el cual el fiscal comunica al imputado, en audiencia ante el juez de garantÝa, que se desarrolla una investigaci¾n penal en su contra por hechos determinados. A partir de la formalizaci¾n, el imputado adquiere derechos plenos de defensa (acceso a la carpeta investigativa, solicitar diligencias) y el proceso penal entra en la etapa formal. No es una acusaci¾n, sino un hito intermedio que posibilita cautelares y fija el punto de inicio del procedimiento penal formal.', 'Ej.: En un caso de robo, el fiscal solicita audiencia de formalizaci¾n. En dicha audiencia, le indica al imputado ôse le investiga por robo ocurrido el 5 de marzo enàö, ante el juez. Desde entonces, el imputado puede pedir pruebas, y el fiscal ya puede solicitar medidas cautelares (p. ej., prisi¾n preventiva).', 'Art. 229 CPP (define la formalizaci¾n como la comunicaci¾n al imputado, ante juez, de la existencia de una investigaci¾n en su contra)', '', '', '["La formalizaci¾n ha generado debate respecto a su oportunidad: fiscalÝa suele demorarse hasta reunir antecedentes suficientes, lo que para la defensa puede implicar investigaciones ôsecretasö prolongadas. El Tribunal Constitucional ha se±alado que la formalizaci¾n marca el inicio del plazo de investigaci¾n y del control judicial, garantizando derechos del imputado. TambiÚn se discute su no-recurribilidad: al no ser resoluci¾n, no admite recursos, lo que ha sido criticado por limitar el control; no obstante, se puede reclamar ante superiores del MP por abuso en formalizaciones arbitrarias, correctivo mßs bien interno."]'),
('DP-028', 'Medidas Cautelares Personales', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Restricciones impuestas al imputado durante la investigaci¾n para asegurar fines del proceso (comparecencia, seguridad de la sociedad o de la vÝctima). Van desde la prisi¾n preventiva (privaci¾n de libertad) hasta medidas menos gravosas: arresto domiciliario, prohibici¾n de acercarse a la vÝctima, firma peri¾dica, arraigo (prohibici¾n de salir del paÝs), entre otras. La prisi¾n preventiva procede solo si las demßs resultan insuficientes y existieren antecedentes de peligro de fuga o de peligro para la seguridad.', 'Ej.: A un imputado por robo con intimidaci¾n, sin antecedentes penales, el juez de garantÝa le decreta arresto domiciliario nocturno y arraigo nacional en lugar de prisi¾n preventiva, al considerar que con esas medidas se asegura su sujeci¾n al procedimiento y la seguridad de la vÝctima.', 'Arts. 140-146 CPP (presupuestos de la prisi¾n preventiva: indicios de delito y necesidad por peligro de fuga o para la sociedad); Art. 155 CPP (medidas cautelares menos gravosas)', '', '', '["La aplicaci¾n de la prisi¾n preventiva ha sido foco de intensa crÝtica: por un lado, jueces y fiscales la emplean extensamente (se habla de ôprisi¾n preventiva como pena anticipadaö), suscitando reproches de vulneraci¾n de la presunci¾n de inocencia. La Corte Suprema ha reiterado su carßcter excepcional y exigido fundamentar en concreto la necesidad de la medida, revocando prisiones preventivas arbitrarias vÝa recurso de amparo", "Por otro lado, clamor social ante delitos violentos lleva a presiones para endurecer su uso. El debate se centra en equilibrar seguridad p·blica y derecho a la libertad: reformas recientes han acotado plazos mßximos de investigaci¾n con detenido, para impedir prolongaciones indefinidas de cautelares personales."]'),
('DP-030', 'Audiencia de Preparaci¾n de Juicio Oral', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'TambiÚn llamada etapa intermedia, es la audiencia ante el juez de garantÝa en que se depura el caso que irß a juicio oral. Tras la formalizaci¾n y cierre de la investigaci¾n, el fiscal presenta la acusaci¾n e en esta audiencia se discuten las pruebas que cada parte pretende llevar al juicio. El juez resuelve sobre su admisibilidad, excluyendo pruebas ilÝcitas o impertinentes, y dicta el auto de apertura de juicio oral con los hechos precisos de acusaci¾n y la n¾mina de prueba admitida.', 'Ej.: En un caso de lesiones graves, en la audiencia preparatoria el defensor se opone a la incorporaci¾n de cierta declaraci¾n por haber sido obtenida sin abogado (prueba ilÝcita). El juez de garantÝa acoge la objeci¾n y excluye esa declaraci¾n. Luego de debatir todas las pruebas, el juez dicta auto de apertura, estableciendo quÚ pruebas sÝ se rendirßn ante el tribunal oral.', 'Arts. 259-274 CPP (acusaci¾n y preparaci¾n del juicio oral: intercambio de escritos acusatorios, audiencia para acuerdos probatorios, admisibilidad de prueba y auto de apertura)', '', '', '["Esta fase equilibra garantÝas y eficiencia: permite filtrar prueba ilegal o irrelevante antes del juicio. Sin embargo, se debate si los jueces de garantÝa a veces aplican un estßndar demasiado laxo o estricto al excluir pruebas. Por ej., jurisprudencia diversa en criterios de exclusi¾n de testigos no individualizados en acusaci¾n ha generado incertidumbre. TambiÚn se analiza la conciliaci¾n en delitos no graves durante esta etapa: algunos la fomentan para descongestionar (ej. acuerdo reparatorio), mientras otros advierten que puede trivializar la acci¾n penal. La tendencia apunta a fortalecer esta audiencia como espacio clave de preparaci¾n, enfatizando principios de descubrimiento probatorio recÝproco y lealtad procesal."]'),
('DP-031', 'Juicio Oral', 'Derecho Procesal', 'Procedimiento Penal (Reforma Procesal Penal)', 'Fase culminante del proceso penal, donde un tribunal colegiado (3 jueces profesionales) conoce p·blicamente, en forma oral y contradictoria, la prueba sobre la acusaci¾n formulada, para dictar veredicto y sentencia. Rige la inmediaci¾n (los jueces deben presenciar directamente la rendici¾n de pruebas) e la continuidad (audiencia ininterrumpida hasta conclusi¾n). El juicio oral es p·blico, salvo excepciones para proteger bienes jurÝdicos sensibles.', 'Ej.: En un juicio oral por robo, comparecen los testigos de cargo y descargo, se presentan peritajes (todo en audiencia oral). Los jueces escuchan los alegatos finales de fiscal y defensa y luego deliberan para emitir veredicto absolutorio o condenatorio, y en caso de condena dictan la sentencia con la pena correspondiente.', 'Arts. 280-303 CPP (principios del juicio oral: publicidad, oralidad, inmediaci¾n, concentration; desarrollo: orden de prueba, interrogatorios, alegatos finales)', '', '', '["Un desafÝo es la valoraci¾n de la prueba conforme a la sana crÝtica: al no haber actas escritas integrales, la convicci¾n de los jueces se forma por lo percibido directamente, lo que dificulta su revisi¾n en recursos (solo vÝa nulidad por infracci¾n de garantÝas). Esto ha generado discusiones sobre la necesidad de grabaci¾n audiovisual completa y su alcance en el recurso de nulidad. Asimismo, se tensiona la celeridad con el derecho de defensa: juicios marat¾nicos pueden afectar la concentraci¾n de partes y jueces; la jurisprudencia ha anulado juicios por violar la continuidad (suspensiones excesivas), reforzando que la fragmentaci¾n del juicio atenta contra la inmediaci¾n. En suma, el juicio oral realiza plenamente el contradictorio, pero impone altas exigencias logÝsticas y personales al sistema penal."]'),
('DP-035', 'Jurisdicci¾n', 'Derecho Procesal', 'Orgßnico', 'Poder-deber que tienen los tribunales para conocer y resolver, por medio del proceso y con efecto de cosa juzgada, los conflictos de intereses de relevancia jurÝdica.', 'La Corte Suprema resolviendo un recurso extraordinario de revisi¾n o casaci¾n en el fondo con autoridad soberana plena,.', 'Colombo Campbell', '', '', '["Es indelegable e improrrogable.", "Su falta genera la inexistencia procesal del acto."]'),
('DP-036', 'Competencia', 'Derecho Procesal', 'Orgßnico', 'Esfera, grado o medida fijada por el legislador para que la jurisdicci¾n se ejerza por cada tribunal especÝfico.', 'Un juez de letras conociendo de un asunto civil de mayor cuantÝa en su territorio jurisdiccional.', 'Art. 108 COT', '', '', '["Puede delegarse parcialmente mediante exhortos.", "Su infracci¾n o falta genera la nulidad procesal."]'),
('DP-037', 'Pr¾rroga de la Competencia', 'Derecho Procesal', 'Orgßnico', 'Acuerdo expreso o tßcito de las partes para otorgar competencia a un tribunal que naturalmente no es el competente para conocer del asunto.', 'El demandado contesta una demanda civil ante un tribunal de distinto territorio sin alegar la incompetencia.', 'Art. 187 CPC', '', '', '["Procede solo en asuntos civiles contenciosos de primera instancia.", "Permite alterar ·nicamente el factor territorio, nunca la materia o fuero."]'),
('DP-038', 'Regla de Radicaci¾n', 'Derecho Procesal', 'Orgßnico', 'Principio normativo que establece que, radicado con arreglo a la ley el conocimiento de un negocio ante tribunal competente, no se alterarß esta competencia por causa sobreviniente.', 'Un demandado cambia de domicilio a otra ciudad durante el juicio, pero el tribunal original sigue siendo el competente para fallar,.', 'Art. 109 COT', '', '', '["Requiere la intervenci¾n formal de un tribunal competente mediante notificaci¾n vßlida.", "Genera el estado de litis pendencia y fija irremediablemente la competencia."]'),
('DP-039', 'Equivalentes Jurisdiccionales', 'Derecho Procesal', 'TeorÝa General', 'Formas de soluci¾n de conflictos distintas del proceso jurisdiccional que producen un efecto vinculante asimilable a la cosa juzgada,.', 'La celebraci¾n de un contrato de transacci¾n o un avenimiento aprobado por el juez,.', 'Doctrina Procesal (Carnelutti)', '', '', '["Constituyen actos de autocomposici¾n que ponen tÚrmino anticipado al litigio.", "Producen eficacia de cosa juzgada material al igual que una sentencia definitiva."]'),
('DP-032', 'Proceso', 'Derecho Procesal', 'TeorÝa General', 'Medio id¾neo para dirimir imparcialmente, por acto de juicio de autoridad, un conflicto de relevancia jurÝdica mediante una resoluci¾n que eventualmente puede adquirir la fuerza de la cosa juzgada,.', 'La totalidad de la secuela de actos desde la llegada hasta el cumplimiento de la sentencia para el cobro de una deuda.', 'Doctrina Procesal', '', '', '["Es un concepto abstracto y ·nico enfocado en la finalidad de resolver la controversia.", "Su culminaci¾n l¾gica y esperada es la dictaci¾n de una sentencia firme."]'),
('DP-033', 'Procedimiento', 'Derecho Procesal', 'TeorÝa General', 'Conjunto de formalidades, trßmites, ritos externos o actuaciones a travÚs de las cuales se desarrolla materialmente el proceso judicial,.', 'El juicio ordinario que establece etapas estrictas de discusi¾n, prueba y fallo.', 'Doctrina Procesal', '', '', '["Constituye el aspecto exterior, formal y dinßmico del fen¾meno procesal.", "Existen m·ltiples procedimientos (ordinario, sumario, ejecutivo) para sustanciar procesos de diversa naturaleza."]'),
('DP-034', 'Juicio', 'Derecho Procesal', 'TeorÝa General', 'Controversia jurÝdica y actual producida entre dos o mßs personas sobre un derecho y que se somete a la decisi¾n jurisdiccional de un tribunal,.', 'El litigio puntual entre arrendador y arrendatario por el no pago de las rentas,.', 'Casarino Viterbo', '', '', '["Sus elementos constitutivos son la contienda, las partes y el tribunal llamado a resolverla.", "Suele utilizarse doctrinariamente como el procedimiento especÝfico a travÚs del cual se desarrolla el proceso."]'),
('DP-040', 'Partes', 'Derecho Procesal', 'Sujetos Procesales', 'Aquellas personas que sostienen formalmente ante un tribunal una contienda jurÝdica y actual acerca de sus propios derechos e intereses.', 'El acreedor demandante que exige el pago y el deudor demandado que rechaza la deuda.', 'Doctrina Procesal', '', '', '["Se clasifican fundamentalmente en directas o principales e indirectas o terceros.", "Para intervenir vßlidamente requieren contar con capacidad procesal."]'),
('DP-041', 'Terceros', 'Derecho Procesal', 'Sujetos Procesales', 'Personas distintas del demandante y del demandado que comparecen al juicio por tener comprometido en Úl un derecho, sosteniendo peticiones.', 'Un legatario que decide intervenir voluntariamente en el juicio donde los herederos discuten la nulidad del testamento.', 'Doctrina Procesal', '', '', '["Su intervenci¾n procedimental se denomina jurÝdicamente como tercerÝa.", "Se subclasifican en terceros coadyuvantes, independientes y excluyentes."]'),
('DP-042', 'Patrocinio', 'Derecho Procesal', 'Comparecencia en Juicio', 'Contrato por el cual las partes o interesados en un asunto judicial encomiendan a un abogado habilitado la defensa tÚcnica de sus pretensiones ante los tribunales.', 'Un abogado que asume la direcci¾n jurÝdica de un caso asumiendo la firma y responsabilidad en el primer escrito.', 'Ley N║ 18.120', '', '', '["El profesional asume la responsabilidad civil, criminal y disciplinaria de la defensa.", "Se diferencia del mandato judicial en que este ·ltimo se restringe a la mera representaci¾n procesal."]'),
('DP-043', 'Mandato Judicial', 'Derecho Procesal', 'Comparecencia en Juicio', 'Contrato procesal mediante el cual una persona otorga a otra facultades suficientes para que la represente formal y vßlidamente ante los tribunales de justicia.', 'Una persona confiere mandato mediante escritura p·blica a un procurador del n·mero para tramitar su caso civil,.', 'Ley N║ 18.120', '', '', '["Debe recaer obligatoriamente en abogados habilitados, procuradores del n·mero o postulantes de la corporaci¾n.", "Su no constituci¾n legal acarrea que el tribunal tenga por no presentado el escrito respectivo."]'),
('DP-044', 'Demanda', 'Derecho Procesal', 'Juicio Ordinario', 'Acto procesal introductivo de instancia por virtud de la cual el actor somete su pretensi¾n al juez, con las formas requeridas por la ley, pidiendo una sentencia favorable en su interÚs.', 'El escrito principal mediante el cual el actor exige indemnizaci¾n por incumplimiento de un contrato.', 'Art. 254 CPC / Couture', '', '', '["Es la vÝa formal y material a travÚs de la cual se ejercita la acci¾n procesal.", "Fija los lÝmites del juicio y el marco sobre el cual deberß recaer la congruencia de la sentencia definitiva."]'),
('DP-045', 'Emplazamiento', 'Derecho Procesal', 'Disposiciones Comunes', 'Notificaci¾n de la demanda, a la cual se agrega la orden de que el notificado comparezca al tribunal dentro del tÚrmino se±alado por Úste.', 'El receptor notifica la demanda civil al deudor, abriendo el plazo fatal legal para que este conteste.', 'Doctrina Procesal', '', '', '["Se compone de dos elementos copulativos: la notificaci¾n legal y el transcurso Ýntegro del plazo.", "Su omisi¾n o defecto grave configura un vicio esencial que anula la validez de todo el procedimiento."]'),
('DP-046', 'Notificaci¾n Personal', 'Derecho Procesal', 'Notificaciones', 'Forma legal de notificaci¾n que consiste en entregar directamente a la persona a quien se debe notificar, en forma fÝsica, copia Ýntegra de la resoluci¾n y de la solicitud respectiva.', 'El receptor judicial entrega en propias manos del demandado la resoluci¾n que admite a tramitaci¾n la primera demanda civil,.', 'Art. 40 CPC', '', '', '["Es la regla obligatoria e ineludible para la primera notificaci¾n a las partes en toda gesti¾n judicial,.", "Garantiza de forma directo el efectivo conocimiento del acto procesal fundamental."]'),
('DP-047', 'Notificaci¾n por el Estado Diario', 'Derecho Procesal', 'Notificaciones', 'Ficci¾n legal en que se entiende vßlidamente notificada una resoluci¾n por el solo hecho de incluirse la noticia de su dictaci¾n en una n¾mina electr¾nica diaria,.', 'La resoluci¾n de mero trßmite de traslado se incorpora en el sistema informßtico del tribunal quedando las partes legalmente informadas.', 'Art. 50 CPC', '', '', '["Constituye la regla generalÝsima para notificar actos de tramitaci¾n normal en el proceso civil.", "La inclusi¾n se realiza en un estado electr¾nico disponible permanentemente en el portal del Poder Judicial."]'),
('DP-048', 'Plazo Fatal', 'Derecho Procesal', 'Plazos Procesales', 'Espacio de tiempo en que la posibilidad de ejercer un derecho o ejecutar un acto procesal se extingue automßticamente a su vencimiento por el solo ministerio de la ley.', 'El plazo legal de quince dÝas para contestar la demanda ordinaria que precluye automßticamente si no se presenta el escrito a tiempo.', 'Art. 64 CPC', '', '', '["La gran mayorÝa de los plazos que establece el C¾digo de Procedimiento Civil revisten esta naturaleza perentoria.", "No requieren de declaraci¾n judicial ni certificado de rebeldÝa previo para que opere su pleno efecto preclusivo."]'),
('DP-049', 'RebeldÝa', 'Derecho Procesal', 'Plazos Procesales', 'Situaci¾n jurÝdica que se le produce al litigante que deja de evacuar un trßmite o de practicar una diligencia en el plazo que se±ala el tribunal.', 'El demandante no evac·a el trßmite de observaciones a la prueba, por lo que el tribunal declara evacuado el trßmite en su rebeldÝa.', 'Art. 78 CPC', '', '', '["Obliga al tribunal, de oficio o a petici¾n de parte, a declarar el trßmite por evacuado y dar curso progresivo a la sustanciaci¾n.", "Puede ser objeto de rescisi¾n si la parte demuestra fehacientemente haber estado impedida por fuerza mayor."]'),
('DP-050', 'Excepciones Dilatorias', 'Derecho Procesal', 'Juicio Ordinario', 'Defensas procesales que tienen por objeto corregir los vicios de validez procesal al momento de formarse la relaci¾n jurÝdica y corregir el procedimiento.', 'El demandado alega la incompetencia del tribunal o la ineptitud del libelo por falta de claridad en las peticiones de la demanda.', 'Art. 303 CPC', '', '', '["Se tramitan obligatoriamente como un incidente de previo y especial pronunciamiento.", "Buscan sanear y purificar la relaci¾n jurÝdica procesal antes de entrar al debate del fondo."]'),
('DP-051', 'Excepciones Perentorias', 'Derecho Procesal', 'Juicio Ordinario', 'Defensas jurÝdicas de carßcter sustancial que miran directamente al fondo del asunto y tienen por exclusivo objeto enervar, destruir o extinguir la acci¾n deducida.', 'Frente a la demanda de cobro de dinero, el demandado contesta oponiendo el pago efectivo de la deuda o la prescripci¾n.', 'Doctrina Procesal', '', '', '["A diferencia de las dilatorias, no suspenden el proceso, sino que persiguen el rechazo Ýntegro de la demanda en la sentencia final.", "Suelen coincidir e identificarse directamente con los modos normativos civiles de extinguir las obligaciones."]'),
('DP-052', 'Reconvenci¾n', 'Derecho Procesal', 'Juicio Ordinario', 'Demanda procesal nueva que el demandado deduce en contra del demandante original en el propio escrito de contestaci¾n de la demanda.', 'En un juicio ordinario por incumplimiento contractual, el demandado contesta y a su vez demanda exigiendo indemnizaci¾n por mejoras,.', 'Art. 314 CPC', '', '', '["Se tramitan conjuntamente y se falla de forma obligatoria en la misma sentencia definitiva de la acci¾n principal.", "Materializa el principio de economÝa procesal y evita el alto riesgo de dictar sentencias contradictorias."]'),
('DP-053', 'Incidentes', 'Derecho Procesal', 'Disposiciones Comunes', 'Toda cuesti¾n procedimental accesoria a un juicio principal que requiere de un pronunciamiento judicial especial, con o sin audiencia de partes,.', 'Un litigante promueve la nulidad de una notificaci¾n defectuosa o solicita el alzamiento judicial de una medida precautoria.', 'Art. 82 CPC', '', '', '["Se pueden subclasificar procesalmente en incidentes ordinarios, especiales, de previo y especial pronunciamiento, conexos o inconexos,.", "Su tramitaci¾n comprende una etapa de discusi¾n, prueba y un fallo emitido tÝpicamente en un auto o interlocutoria,."]'),
('DP-054', 'Acumulaci¾n de Autos', 'Derecho Procesal', 'Incidentes Especiales', 'Incidente procesal especial que tiene por objeto obtener que el tribunal ordene agrupar materialmente dos o mßs procesos pendientes y conexos para tramitarlos y fallarlos conjuntamente.', 'Se acumula un juicio declarativo de nulidad de contrato a otro que persigue el cobro coactivo del mismo.', 'Art. 92 CPC', '', '', '["Su finalidad suprema y fundante es mantener la continencia de la causa y evitar el pronunciamiento de sentencias contradictorias.", "Exigen copulativamente que los juicios afectados se encuentren en instancias anßlogas y sometidos al mismo procedimiento legal."]'),
('DP-055', 'Abandono del Procedimiento', 'Derecho Procesal', 'Incidentes Especiales', 'Sanci¾n procesal que declara el tÚrmino anticipado del procedimiento por la inactividad de las partes que han cesado en su prosecuci¾n durante seis meses.', 'El juicio civil se estanca ocho meses sin que nadie pida prueba, por lo que el demandado solicita al juez que declare extinguido el proceso.', 'Art. 152 CPC', '', '', '["Provoca la pÚrdida de todo lo obrado en el juicio, castigando la negligencia de los litigantes.", "No extingue directamente la pretensi¾n ni la acci¾n material subyacente, permitiendo al actor entablar una demanda nueva."]'),
('DP-056', 'Desistimiento de la Demanda', 'Derecho Procesal', 'Incidentes Especiales', 'Acto jurÝdico procesal unilateral, formalizado por el actor, mediante el cual manifiesta su voluntad de renunciar a la pretensi¾n hecha valer, extinguiendo el proceso,.', 'El demandante, percatßndose de un error estratÚgico insalvable, presenta un escrito desistiÚndose tras haber notificado al demandado.', 'Art. 148 CPC', '', '', '["Se tramitara rigurosamente como un incidente y requiere una resoluci¾n jurisdiccional interlocutoria que lo acoja.", "Produce un efecto definitivo extinguiendo la pretensi¾n procesal originando la fuerza de cosa juzgada."]'),
('DP-057', 'Medidas Prejudiciales', 'Derecho Procesal', 'Medidas Cautelares', 'Providencias de naturaleza preparatoria o conservadora que puede o debe decretar el tribunal, antes del inicio formal de un juicio, para hacer posible o facilitar las futuras acciones o defensas.', 'Ej.: Un futuro demandante solicita la exhibici¾n judicial de los libros de contabilidad de la empresa adversaria para fundar precisamente su demanda,.', 'Art. 273 CPC', '', '', '["La doctrina procesal las subclasifica en preparatorias, probatorias y netamente precautorias prejudiciales.", "Buscan garantizar razonablemente que la entrada al futuro litigio sea con los elementos de juicio y pruebas indispensables."]'),
('DP-058', 'Medidas Precautorias', 'Derecho Procesal', 'Medidas Cautelares', 'Providencias dictadas por el juez durante el curso del juicio que estßn dirigidas a asegurar el resultado prßctico y el cumplimiento patrimonial de la acci¾n deducida,.', 'La retenci¾n de dineros bancarios del demandado o la prohibici¾n judicial de celebrar actos sobre un inmueble disputado.', 'Art. 290 CPC', '', '', '["Exigen comprobar al menos la presunci¾n grave del derecho que se reclama y requieren cauci¾n en ciertos casos.", "Son resoluciones esencialmente provisionales, limitadas a los bienes necesarios y pueden ser sustituidas por garantÝas suficientes."]'),
('DP-059', 'Resoluciones Judiciales', 'Derecho Procesal', 'TeorÝa de las Resoluciones', 'Acto jurÝdico procesal que emana formalmente del tribunal o sus auxiliares, destinado a dar curso progresivo al procedimiento (sustanciar) o a fallar la controversia del juicio.', 'Desde un simple decreto que ordena el "Traslado" de un escrito hasta la extensa sentencia definitiva que condena al deudor,.', 'Art. 158 CPC', '', '', '["El legislador las clasifica jerßrquicamente en sentencias definitivas, sentencias interlocutorias, autos y decretos o proveÝdos.", "Su correcta naturaleza legal determina la procedencia admisible de los recursos procesales y sus efectos de cosa juzgada."]'),
('DP-060', 'Sentencia Definitiva', 'Derecho Procesal', 'TeorÝa de las Resoluciones', 'Resoluci¾n magna que pone fin a la instancia jurisdiccional, resolviendo y zanjando Ýntegramente la cuesti¾n o asunto que ha sido objeto principal del pleito.', 'El fallo del juez de letras que, al terminar todo el proceso civil, condena al ejecutado al pago del crÚdito insoluto.', 'Art. 158 CPC', '', '', '["Debe cumplir con formalidades rigurosas que incluyen necesariamente una parte expositiva, considerativa y resolutiva,.", "Es la resoluci¾n judicial natural y esperada sobre la cual recae con mßxima intensidad el efecto inmutable de la cosa juzgada."]'),
('DP-061', 'Recurso Procesal', 'Derecho Procesal', 'Medios de Impugnaci¾n', 'Acto jurÝdico procesal de la parte agraviada, ejercido mediante el cual impugna formalmente una resoluci¾n judicial no ejecutoriada, solicitando su revisi¾n para anularla, modificarla o revocarla,.', 'El litigante perdidoso apela el fallo condenatorio de primera instancia para que la Corte de Apelaciones respectiva lo revise en el fondo,.', 'Doctrina Procesal (Mosquera / Maturana)', '', '', '["Exige de forma ineludible la existencia de un agravio o perjuicio directo causado al interviniente por la decisi¾n del tribunal,.", "Constituyen el pilar fundamental que da vida y materializa la garantÝa procedimental de la doble instancia judicial."]')
